import * as React from 'react';

export type RouteId = 'home' | 'projects' | 'settings';

export const ROUTES: Record<RouteId, { path: string; title: string }> = {
  home: { path: '#/', title: 'Главная' },
  projects: { path: '#/projects', title: 'Проекты' },
  settings: { path: '#/settings', title: 'Настройки' },
};

function parseHash(hash: string): RouteId {
  const found = (Object.keys(ROUTES) as RouteId[]).find((id) => ROUTES[id].path === hash);
  return found ?? 'home';
}

/** Minimal hash router: `#/`, `#/projects`, `#/settings`. */
export function useHashRoute() {
  const [route, setRoute] = React.useState<RouteId>(() => parseHash(window.location.hash));

  React.useEffect(() => {
    const onChange = () => setRoute(parseHash(window.location.hash));
    window.addEventListener('hashchange', onChange);
    return () => window.removeEventListener('hashchange', onChange);
  }, []);

  React.useEffect(() => {
    document.title = `${ROUTES[route].title} · Gravity Demo`;
  }, [route]);

  const navigate = React.useCallback((id: RouteId) => {
    window.location.hash = ROUTES[id].path;
  }, []);

  return { route, navigate };
}
EOF
cat > src/theme.ts <<'EOF'
import * as React from 'react';

export type AppTheme = 'light' | 'dark';

const STORAGE_KEY = 'gravity-demo-theme';

function getInitialTheme(): AppTheme {
  const saved = window.localStorage.getItem(STORAGE_KEY);
  if (saved === 'light' || saved === 'dark') {
    return saved;
  }
  return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}

/** Light/dark theme state, persisted in localStorage. */
export function useAppTheme() {
  const [theme, setTheme] = React.useState<AppTheme>(getInitialTheme);

  React.useEffect(() => {
    window.localStorage.setItem(STORAGE_KEY, theme);
  }, [theme]);

  const toggleTheme = React.useCallback(
    () => setTheme((current) => (current === 'light' ? 'dark' : 'light')),
    [],
  );

  return { theme, setTheme, toggleTheme };
}
EOF
cat > src/App.tsx <<'EOF'
import * as React from 'react';
import { AsideHeader, FooterItem } from '@gravity-ui/navigation';
import type { AsideHeaderItem } from '@gravity-ui/navigation';
import { Briefcase, Gear, House, LayoutCells, Moon, Sun } from '@gravity-ui/icons';
import { ThemeProvider } from '@gravity-ui/uikit';

import { ROUTES, useHashRoute } from './routes';
import { useAppTheme } from './theme';
import { HomePage } from './pages/HomePage';
import { ProjectsPage } from './pages/ProjectsPage';
import { SettingsPage } from './pages/SettingsPage';

export function App() {
  const { theme, setTheme, toggleTheme } = useAppTheme();
  const { route, navigate } = useHashRoute();
  // Collapse the sidebar by default on narrow screens.
  const [compact, setCompact] = React.useState(() => window.innerWidth < 768);

  const menuItems: AsideHeaderItem[] = [
    { id: 'home', title: ROUTES.home.title, icon: House, href: ROUTES.home.path, current: route === 'home' },
    {
      id: 'projects',
      title: ROUTES.projects.title,
      icon: Briefcase,
      href: ROUTES.projects.path,
      current: route === 'projects',
    },
    {
      id: 'settings',
      title: ROUTES.settings.title,
      icon: Gear,
      href: ROUTES.settings.path,
      current: route === 'settings',
    },
  ];

  const isDark = theme === 'dark';

  const renderPage = () => {
    switch (route) {
      case 'projects':
        return <ProjectsPage />;
      case 'settings':
        return (
          <SettingsPage
            theme={theme}
            onThemeChange={setTheme}
            compact={compact}
            onCompactChange={setCompact}
          />
        );
      default:
        return <HomePage onNavigate={navigate} />;
    }
  };

  return (
    <ThemeProvider theme={theme}>
      <AsideHeader
        logo={{ text: 'Gravity Demo', icon: LayoutCells, href: ROUTES.home.path }}
        compact={compact}
        onChangeCompact={setCompact}
        menuItems={menuItems}
        renderFooter={({ compact: isCompact }) => (
          <FooterItem
            id="theme"
            title={isDark ? 'Светлая тема' : 'Тёмная тема'}
            icon={isDark ? Sun : Moon}
            compact={isCompact}
            onItemClick={toggleTheme}
          />
        )}
        renderContent={() => <main className="app-content">{renderPage()}</main>}
      />
    </ThemeProvider>
  );
}
EOF
